mapper.sql:
FROM knowledge_item i INNER JOIN knowledge_release r ON r.knowledge_id = i.id AND r.organ_id = i.organ_id AND (r.delete_flag = 0 OR r.delete_flag IS NULL) AND r.release_status = 'PUBLISHED' AND r.active_revision_id IS NOT NULL INNER JOIN knowledge_revision v ON v.id = r.active_revision_id AND v.organ_id = i.organ_id AND v.knowledge_id = i.id AND (v.delete_flag = 0 OR v.delete_flag IS NULL) AND v.revision_status = 'PUBLISHED' AND v.index_status = 'INDEXED' WHERE i.visibility = 'PUBLIC' AND i.status = 'ACTIVE' AND (i.delete_flag = 0 OR i.delete_flag IS NULL)
AND i.category_id = #{categoryId, jdbcType=BIGINT}
AND (i.knowledge_name LIKE CONCAT('%', #{keyword, jdbcType=VARCHAR}, '%') OR i.description LIKE CONCAT('%', #{keyword, jdbcType=VARCHAR}, '%'))
